def solve(g):
    g = np.array(g); n, m = g.shape
    out = g.copy()
    blocks = []
    for r in range(n-1):
        for c in range(m-1):
            v = g[r,c]
            if v != 0 and v == g[r+1,c] == g[r,c+1] == g[r+1,c+1]:
                blocks.append((r,c))
    for (r,c) in blocks:
        # diagonal slots: TL, TR, BR, BL (clockwise order)
        slots = [(r-1,c-1),(r-1,c+2),(r+2,c+2),(r+2,c-1)]
        cols = [int(g[i,j]) if 0<=i<n and 0<=j<m else 0 for i,j in slots]
        # rotate clockwise: TL<-BL, TR<-TL, BR<-TR, BL<-BR
        new = [cols[3], cols[0], cols[1], cols[2]]
        dirs = [(-1,-1),(-1,1),(1,1),(1,-1)]
        corners = [(r,c),(r,c+1),(r+1,c+1),(r+1,c)]
        for (cr,cc),(dr,dc),col in zip(corners,dirs,new):
            if col==0: continue
            i,j=cr+dr,cc+dc
            while 0<=i<n and 0<=j<m:
                out[i,j]=col; i+=dr; j+=dc
    return out
